// Find all buttons/links in the top area that could be the gear icon for settings
const items = [];
document.querySelectorAll('button, a').forEach(el => {
  const aria = el.getAttribute('aria-label') || '';
  const title = el.getAttribute('title') || '';
  const cls = el.className || '';
  const html = el.innerHTML.slice(0, 60);
  items.push({tag: el.tagName, aria: aria.slice(0,60), title: title.slice(0,60), cls: cls.slice(0,80), html: html.replace(/\s+/g,' ').trim()});
});
items.filter(i => /settings|gear|cog|dashboard settings/i.test(i.aria + ' ' + i.title + ' ' + i.cls + ' ' + i.html))

// Get all buttons/links with their full inner HTML
document.querySelectorAll('button').forEach(b => {
  const aria = b.getAttribute('aria-label') || '';
  const title = b.getAttribute('title') || '';
  const html = b.innerHTML.replace(/\s+/g,' ').trim().slice(0,100);
  console.log(`button aria="${aria}" title="${title}" html="${html}"`);
});
